import java.util.*;
public class MinSwaps {
    public static int minSwaps(int[] arr) {
        int n = arr.length;
        ArrayList<Pair<Integer, Integer>> list = new ArrayList<>();
        for (int i = 0; i < n; i++) list.add(new Pair<>(arr[i], i));
        list.sort(Comparator.comparingInt(a -> a.getKey()));
        boolean[] vis = new boolean[n];
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (vis[i] || list.get(i).getValue() == i) continue;
            int cycle_size = 0, j = i;
            while (!vis[j]) {
                vis[j] = true;
                j = list.get(j).getValue();
                cycle_size++;
            }
            if (cycle_size > 0) ans += (cycle_size - 1);
        }
        return ans;
    }
}

# Functions: name it so the next reader needs no comments.
def celsius_to_fahrenheit(celsius):
    return celsius * 9 / 5 + 32

def fahrenheit_to_celsius(fahrenheit):
    return (fahrenheit - 32) * 5 / 9

def describe_temperature(celsius):
    """Return a short human-readable summary of a temperature."""
    fahrenheit = celsius_to_fahrenheit(celsius)
    if celsius <= 0:
        return f"{celsius}C ({fahrenheit:.1f}F) - freezing point"
    if celsius >= 35:
        return f"{celsius}C ({fahrenheit:.1f}F) - heat warning"
    return f"{celsius}C ({fahrenheit:.1f}F) - comfortable"

print(describe_temperature(20))    # 20C (68.0F) - comfortable
print(describe_temperature(38))    # 38C (100.4F) - heat warning

