/* A tiny expression evaluator, built on a table of operations.
   This is the pattern that turns C code from a pile of if-statements
   into something extensible. */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef double (*BinaryOp)(double, double);

static double op_add(double a, double b) { return a + b; }
static double op_sub(double a, double b) { return a - b; }
static double op_mul(double a, double b) { return a * b; }
static double op_div(double a, double b) { return b == 0.0 ? 0.0 : a / b; }

typedef struct {
    const char *symbol;
    BinaryOp    apply;
    int         precedence;
} Operation;

static const Operation ops[] = {
    { "+", op_add, 1 },
    { "-", op_sub, 1 },
    { "*", op_mul, 2 },
    { "/", op_div, 2 },
};

#define OP_COUNT ((int)(sizeof ops / sizeof ops[0]))

static const Operation *find_op(const char *token)
{
    for (int i = 0; i < OP_COUNT; i++) {
        if (strcmp(ops[i].symbol, token) == 0) return &ops[i];
    }
    return NULL;
}

int main(void)
{
    /* Adding a new operator is: one function + one table row. */
    /* No switch to edit, no else-if chain, and the compiler checks
       that the signature matches. */

    const char *expression = "3 + 4 * 2";
    double lhs = 3.0;
    const char *op_token = "+";
    const char *rhs_token = "4";
    const char *second_op = "*";
    double rhs = 4.0;
    double second_rhs = 2.0;

    const Operation *op1 = find_op(op_token);
    const Operation *op2 = find_op(second_op);

    if (op1 == NULL || op2 == NULL) {
        fprintf(stderr, "Unknown operator in \"%s\"\n", expression);
        return 1;
    }

    double inner = op2->apply(rhs, second_rhs);      /* 4 * 2 = 8 */
    double result = op1->apply(lhs, inner);           /* 3 + 8 = 11 */

    printf("%s = %g\n", expression, result);
    printf("note: * has precedence %d, + has %d, so * is applied first\n",
           op2->precedence, op1->precedence);
    return 0;
}

#include <stdio.h>
#include <stddef.h>

/* sizeof on the array gives the whole thing, not one element. */
static void report_size(void)
{
    int values[5] = {10, 20, 30, 40, 50};

    printf("sizeof values            = %zu bytes\n", sizeof values);
    printf("sizeof values[0]         = %zu bytes\n", sizeof values[0]);
    printf("element count            = %zu\n", sizeof values / sizeof values[0]);

    /* The decay, made visible. */
    int *p = values;
    printf("sizeof p                 = %zu bytes\n", sizeof p);
    printf("&values[0] == p          = %d\n", &values[0] == p);
    printf("*values == values[0]     = %d\n", *values == values[0]);
}

int main(void)
{
    report_size();

    /* Designated initialisers: set element 2 and 4, leave the rest at 0. */
    int sparse[5] = {[2] = 7, [4] = 9};
    for (size_t i = 0; i < sizeof sparse / sizeof sparse[0]; i++) {
        printf("sparse[%zu] = %d\n", i, sparse[i]);
    }

    /* Arrays are not assignable, so copying needs a loop or memcpy. */
    int a[3] = {1, 2, 3};
    int b[3] = {4, 5, 6};
    for (size_t i = 0; i < sizeof a / sizeof a[0]; i++) {
        a[i] = b[i];
    }
    printf("a = {%d, %d, %d}\n", a[0], a[1], a[2]);

    /* Pointer difference counts elements, and one-past-the-end is legal to form. */
    int data[6] = {1, 2, 3, 4, 5, 6};
    int *first = data;
    int *end   = data + 6;          /* formable, never dereference */
    printf("end - first = %td elements\n", end - first);

    /* Walk with a pointer, exactly as indexing would. */
    for (int *cur = first; cur != end; cur++) {
        printf("%d ", *cur);
