{
    printf("%s %s %s\n", color_name(RED), color_name(GREEN), color_name(BLUE));

    struct Value values[3] = {
        { .kind = K_INT,  .u.i = 42 },
        { .kind = K_REAL, .u.r = 3.14159 },
        { .kind = K_STR,  .u.s = strdup("tagged unions") },
    };

    for (size_t i = 0; i < 3; i++) {
        value_print(&values[i]);
        putchar('\n');
