static int write_file(const char *path, const char *text)
{
    FILE *f = fopen(path, "w");        /* truncates immediately */
    if (f == NULL) {
        fprintf(stderr, "cannot write %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fputs(text, f) == EOF) {
        fclose(f);
        return -1;
    }
    if (fclose(f) != 0) {              /* check: buffered errors surface here */
        return -1;
    }
    return 0;
}

int main(void)
{
    const char *path = "demo_output.txt";
    if (write_file(path, "line one\nline two\n") != 0) {
        return 1;
    }

    size_t len = 0;
    char *content = read_file(path, &len);
    if (content == NULL) {
        perror("read_file");
        return 1;
    }

    printf("read %zu bytes:\n%s", len, content);
    free(content);
    remove(path);

    /* Standard streams: diagnostics to stderr, results to stdout. */
    fprintf(stderr, "note: this goes to stderr and is never buffered away\n");

    return 0;
}

#include <stdio.h>

/* Include guards are the portable include-once mechanism. */
#ifndef DEMO_H
#define DEMO_H
enum { BUFFER_SIZE = 4096 };    /* a real compile-time constant symbol */
#define VERSION "1.0.3"
#endif

/* Object-like macro. Fine for a literal message and for text substitution. */
#define PROGRAM_NAME "preprocessor demo"

/* Function-like macro: parenthesise every parameter AND the whole body. */
#define SQUARE(x)      ((x) * (x))
#define MAX(a, b)      ((a) > (b) ? (a) : (b))
#define ARRAY_LEN(a)   (sizeof (a) / sizeof (a)[0])

/* Multi-statement macro: the do/while(0) wrapper makes it one statement. */
#define CHECK(cond) \
    do { \
        if (!(cond)) { \
            fprintf(stderr, "%s:%d: check failed: %s\n", \
                    __FILE__, __LINE__, #cond); \
        } \
    } while (0)

/* Debug logging that costs nothing in a release build. */
#ifdef DEBUG
    #define log_dbg(...) fprintf(stderr, "debug: " __VA_ARGS__)
#else
    #define log_dbg(...) ((void)0)
#endif

/* Prefer a static inline function when types and values are involved. */
static inline int max_int(int a, int b)
{
    return a > b ? a : b;
}

int main(void)
{
    printf("%s %s\n", PROGRAM_NAME, VERSION);
    printf("SQUARE(1 + 2) = %d\n", SQUARE(1 + 2));   /* 9, thanks to parens */
    printf("MAX(3, 7)     = %d\n", MAX(3, 7));
    printf("max_int(3, 7) = %d\n", max_int(3, 7));

    int data[] = {10, 20, 30, 40};
    printf("array length  = %zu\n", (size_t)ARRAY_LEN(data));

    CHECK(ARRAY_LEN(data) == 4);

    int i = 0;
    /* MAX(i++, 10) would evaluate i++ twice — use the function instead. */
    printf("safe max      = %d, i = %d\n", max_int(i++, 10), i);

    log_dbg("only printed when built with -DDEBUG\n");

    return 0;
}

int f(int x) {
    return x + 1 > x;   /* no overflow => always true */
}

/* At -O2 gcc emits:
     mov eax, 1
     ret
   The comparison is gone. */

int *p;                 /* indeterminate */
if (flag) p = &value;
*p = 42;                /* UB if !flag */

int  h = INT_MAX;
h = h + 1;              /* signed overflow: UB */

#include <stdio.h>
#include <limits.h>
#include <stdint.h>
#include <stddef.h>

/* ---- defined arithmetic that could have been UB ---- */

/* Unsigned overflow wraps modulo 2^N. This is defined and portable. */
static uint32_t add_mod32(uint32_t a, uint32_t b)
{
    return a + b;                 /* wraps, well-defined */
}

/* Check before a signed operation. */
static int add_int_checked(int a, int b, int *out)
{
    if ((b > 0 && a > INT_MAX - b) || (b < 0 && a < INT_MIN - b)) {
        return -1;                /* would overflow */
    }
    *out = a + b;
    return 0;
}

/* Shift bounds: the shift amount must be in [0, width). */
static uint32_t bit_at(unsigned index)
{
    if (index >= 32) {
        return 0;                 /* refuse instead of shifting by >= 32 (UB) */
    }
    return 1u << index;
}

/* Signed division avoids the INT_MIN / -1 trap, which overflows. */
static int safe_div(int a, int b, int *out)
{
    if (b == 0) return -1;
    if (a == INT_MIN && b == -1) return -1;   /* result not representable */
    *out = a / b;
    return 0;
}

int main(void)
{
    printf("UINT32_MAX + 2 wraps to %u\n", add_mod32(UINT32_MAX, 2));

    int sum;
    if (add_int_checked(INT_MAX, 1, &sum) != 0) {
        printf("would have overflowed — refused\n");
    }

    printf("bit 5 = %u, bit 40 = %u\n", bit_at(5), bit_at(40));

    int q;
    if (safe_div(INT_MIN, -1, &q) != 0) {
        printf("INT_MIN / -1 is not representable — refused\n");
    }

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/* Warnings-as-errors habits, shown in miniature. */

/* Bounded copy: reports truncation instead of overflowing. */
static int append(char *dst, size_t cap, size_t *len, const char *src)
{
    size_t need = strlen(src);
    if (*len + need + 1 > cap) {          /* +1 for the terminator */
        return -1;
    }
    memcpy(dst + *len, src, need);
    *len += need;
    dst[*len] = '\0';
    return 0;
}

/* Bounds-checked write. */
static int put(char *buf, size_t cap, size_t i, char c)
{
    if (i >= cap) {
        return -1;
    }
    buf[i] = c;
    return 0;
}

int main(void)
{
    char buf[8];
    size_t len = 0;
    buf[0] = '\0';

    if (append(buf, sizeof buf, &len, "hello") != 0) {
        fprintf(stderr, "truncated\n");
        return 1;
    }
    if (append(buf, sizeof buf, &len, " world") != 0) {
        fprintf(stderr, "would not fit — reported, not overflowed\n");
    }
    puts(buf);

    for (size_t i = 0; i < 12; i++) {
        if (put(buf, sizeof buf, i, '.') != 0) {
            printf("refused write at index %zu (capacity %zu)\n", i, sizeof buf);
            break;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <limits.h>

/* strtol is the conversion function to use: it reports overflow and
 * where parsing stopped. atoi cannot do either. */
static int parse_int(const char *s, long *out)
{
    char *end = NULL;
    errno = 0;                          /* clear before checking */
    long v = strtol(s, &end, 10);

    if (end == s)          return -1;   /* no digits at all */
    if (*end != '\0')      return -1;   /* trailing garbage */
    if (errno == ERANGE || v < INT_MIN || v > INT_MAX) return -1;
    *out = v;
    return 0;
}

int cmp_asc(const void *a, const void *b);   /* definition below main */

int main(int argc, char **argv)
{
    if (argc != 2) {
        fprintf(stderr, "usage: %s <integer>\n", argv[0]);
        return 2;
    }

    long value;
    if (parse_int(argv[1], &value) != 0) {
        fprintf(stderr, "%s is not a valid int\n", argv[1]);
        return 1;
    }
    printf("parsed %ld\n", value);

    /* ctype requires an unsigned char value; cast every time. */
    const char *text = "Hello, 123 world!";
    size_t letters = 0, digits = 0;
    for (const char *p = text; *p != '\0'; p++) {
        if (isalpha((unsigned char)*p)) letters++;
        if (isdigit((unsigned char)*p)) digits++;
    }
    printf("letters=%zu digits=%zu\n", letters, digits);

    /* qsort with a correct comparator: return the sign, not the difference. */
    int data[] = { 5, 2, 9, 1, 7 };
    size_t n = sizeof data / sizeof data[0];
    qsort(data, n, sizeof data[0], cmp_asc);
    for (size_t i = 0; i < n; i++) {
        printf("%d ", data[i]);
    }
    putchar('\n');

    return 0;
}

int cmp_asc(const void *a, const void *b)
{
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

