# BFS with a list is quadratic before it is correct.
graph = {"a": ["b", "c"], "b": ["d"], "c": ["d"], "d": []}

def bfs(start):
    queue, seen = deque([start]), {start}
    order = []
    while queue:
        node = queue.popleft()      # O(1); list.pop(0) is O(n)
        order.append(node)
        for nxt in graph[node]:
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return order


