        order = v.argsort().argsort().float()     # average ties ignored for simplicity
        return order
    rx, ry = rank(torch.tensor(x)), rank(torch.tensor(y))
    return F.cosine_similarity(rx - rx.mean(), ry - ry.mean(), dim=0).item()

