// client reader: deltas in, one text buffer out
async function streamAnswer(res: Response, onDelta: (t: string) => void) {
  const reader = res.body!.getReader();
  const dec = new TextDecoder();
  let buf = "", text = "", doneFlag = false;
  try {
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      buf += dec.decode(value, { stream: true });
      const frames = buf.split("\n\n");       // SSE frame boundary
      buf = frames.pop()!;                    // keep the partial frame
      for (const frame of frames) {
        const line = frame.split("\n").find(l => l.startsWith("data:"));
        if (!line) continue;
        const payload = line.slice(5).trim();
        if (payload === "[DONE]") { doneFlag = true; continue; }
        const evt = JSON.parse(payload);
        text += evt.delta ?? "";              // provider field names vary
        onDelta(text);
      }
    }
  } catch (e) {
    onDelta(text + "\n\n[connection lost]"); // partial text is not nothing
    return;
  }
  if (!doneFlag) onDelta(text + "\n\n[truncated]"); // closed != finished
}

