export async function runTurn(ctx: Ctx, input: UserTurn): Promise<TurnResult> {
  const trace = newTrace();                       // id rides everywhere
  const req   = await receive(ctx, input);        // auth, validate, quota, idem
  const built = await assemble(req);              // PURE: history + system + data -> messages
  guardInput(built, ctx);                         // moderation / PII / injection checks
  const stream = await callModel(built, {         // transport + retries live here
    timeoutMs: 30000, firstByteMs: 8000,
  });
  const reply = await consume(stream, onDelta);   // stream deltas to client
  const parsed = validate(reply);                 // contract check + one repair
  guardOutput(parsed, ctx);                       // second moderation pass
  await persist(ctx, parsed, trace);              // messages + usage + prompt version
  return parsed;                                  // final event: usage, finish_reason, trace
}

