// full-jitter backoff, deadline-aware, class-aware
async function withRetry(fn, { attempts = 4, deadlineMs = 20_000 } = {}) {
  const start = Date.now();
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try { return await fn(); }
    catch (err) {
      lastErr = err;
      if (!isRetryable(err)) throw err;          // 400/401: stop now
      const base = 250 * 2 ** i, cap = 8_000;
      const wait = Math.random() * Math.min(cap, base);
      const honor = err.retryAfterMs ?? 0;        // provider said wait
      if (Date.now() + Math.max(wait, honor) > deadlineMs) throw err;
      await sleep(Math.max(wait, honor));
    }
  }
  throw lastErr;
}

// idempotent submit: one logical action, one generation
async function submit(userId, idemKey, prompt) {
  const prior = await db.completed.find(userId, idemKey);
  if (prior) return prior;                       // already done - no re-bill
  const result = await withRetry(() => chat(prompt));
  await db.completed.insert(userId, idemKey, result);
  return result;
}

