function assertFits(parts, usage) {
  const count = (s) => tokenizer.encode(s).length;
  const sum = Object.entries(parts)
    .filter(([k]) => k !== "output")
    .reduce((n, [, v]) => n + count(v), 0);
  if (sum + BUDGET.output > BUDGET.window - BUDGET.headroom)
    throw new OverflowError({ sum, policy: "truncate_per_ladder" });
  return { sum, reported: usage?.prompt_tokens ?? null };
}

// calibration: pre-count vs reported, every call
log({ trace_id, estimated: sum, reported: usage.prompt_tokens,
      delta: usage.prompt_tokens - sum, prompt_version });

