  { part: "oldToolResults", reAdd: "retrievable" },
  { part: "middleTurns",    reAdd: "summarised" },
  { part: "oldAssistant",   reAdd: "gist" },
  { part: "earlyUserTurns", reAdd: "bullets" },
];
const FLOORS = { system: 1200, entities: "all", currentTurn: "whole",
                 activeTools: "all" };

function assemble(ctx) {
  let parts = selectParts(ctx);          // per Lesson 3 allocation
  while (overBudget(parts)) {
    const next = LADDER.find(l => parts[l.part].size > 0);
    if (!next) throw new BudgetError("floors exhausted");
    parts[next.part] = shrink(next, parts[next.part]);
  }
  parts.notice = parts.cutAnything
    ? "[earlier turns omitted - ask rather than assume]"
    : "";
  return toMessages(parts);              // whole messages only
}

