export async function runTurn(ctx: Ctx, input: UserTurn): Promise<void> {
  const trace = newTraceId();
  const req = await receive(ctx, input, trace);      // idem + quota here
  const built = await assemblePure(req);             // fixtures-testable
  assertBudget(built, req.tokenBudget);
  guardInput(built.texts, ctx);

  const stream = await callProvider(built, {         // only provider-aware stage
    onAbort: req.signal,
  });

  try {
    const reply = await pipeDeltas(stream, req.sse); // deltas -> client
    const final = validateOrRepair(reply, built);    // schema + finish_reason
    guardOutput(final.text, ctx);
    await persist(ctx, final, { trace, promptVersion: built.version });
    req.sse.final({
      usage: final.usage, finishReason: final.finishReason,
      promptVersion: built.version, traceId: trace,
    });
  } catch (err) {
    req.sse.error(toUserError(err), trace);          // taxonomy, not a dump
    throw err;
  }
}

